// DEV ONLY. A fake `fetch` for the manual-mode endpoints, answering from fixtures/manual_fixture.json, which holds REAL ManualPreview
// responses generated by the studio components (see fixtures/build_manual_fixtures.py). It is not a model: edits that were not
// precomputed answer ok:false. Query switches (all labelled, never on in production):
//   shim_reject=<edit_id,...>  answer those edits with sane:false (to exercise the sanity-rejected UI)
//   shim_extras=1              add SYNTHETIC extras.plapt_affinity to scores (a smooth function of QED, NOT a prediction) to exercise the binding delta UI
//   shim_nosession=1           make POST /api/manual/sessions fail (to exercise the client-side export fallback)
//   shim_latency=<ms>          artificial latency (default 120)
const q = new URLSearchParams(location.search);
const LAT = +(q.get("shim_latency") || 120);
const reject = new Set((q.get("shim_reject") || "").split(",").filter(Boolean));
const extras = q.get("shim_extras") === "1";
const fx = await (await fetch("fixtures/manual_fixture.json")).json();
const sessions = new Map();
const realFetch = window.fetch.bind(window);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const J = (o, status = 200) => new Response(JSON.stringify(o), { status, headers: { "Content-Type": "application/json" } });
const withExtras = (sc) => (sc && extras ? { ...sc, extras: { ...(sc.extras || {}), plapt_affinity: +(5.2 + 2.4 * sc.descriptors.qed + 0.15 * sc.descriptors.logp).toFixed(3) } } : sc);

window.fetch = async (input, init = {}) => {
  const url = new URL(typeof input === "string" ? input : input.url, location.href);
  const p = url.pathname.replace(/^.*?(?=\/api\/)/, "");
  if (!p.startsWith("/api/manual") && p !== "/api/molecules/validate") return realFetch(input, init);
  await sleep(LAT);
  const body = init.body ? JSON.parse(init.body) : null;
  if (p === "/api/molecules/validate") {
    const ok = body.smiles === fx.seed.smiles || Object.keys(fx.applicable).includes(body.smiles);
    return J(ok ? { ok: true, canonical_smiles: body.smiles, molblock: body.smiles === fx.seed.smiles ? fx.seed.molblock : null, score: withExtras(fx.seed.score) } : { ok: false, error: "dev shim: unknown molecule" });
  }
  if (p === "/api/manual/applicable") {
    const smiles = url.searchParams.get("smiles");
    const locked = new Set((url.searchParams.get("locked") || "").split(",").filter(Boolean).map(Number));
    return J((fx.applicable[smiles] || []).filter((e) => !e.site.some((i) => locked.has(i))));
  }
  if (p === "/api/manual/preview") {
    const key = `${body.smiles}|${body.edit_id}|${body.site.join(",")}`;
    const pv = fx.previews[key];
    if (!pv) return J({ ok: false, reason: "dev shim: this edit was not precomputed in the fixture", sane: false });
    const out = { ...pv, score: withExtras(pv.score) };
    if (reject.has(body.edit_id)) { out.sane = false; out.reason = "DEV SHIM: simulated sanity rejection"; }
    return J(out);
  }
  if (p === "/api/manual/sessions" && init.method === "POST") {
    if (q.get("shim_nosession") === "1") return J({ detail: "dev shim: session creation disabled" }, 503);
    const id = "shim" + Math.random().toString(36).slice(2, 8);
    sessions.set(id, { session_id: id, seed_smiles: body.seed_smiles, target_id: body.target_id ?? null, steps: [] });
    return J(sessions.get(id));
  }
  const m = p.match(/^\/api\/manual\/sessions\/([^/]+)\/(steps|export)$/);
  if (m && sessions.has(m[1])) {
    const s = sessions.get(m[1]);
    if (m[2] === "steps") { s.steps.push(body); return J(s); }
    const text = s.steps.map((t) => JSON.stringify({ parent_smiles: t.parent_smiles, edit_id: t.edit_id, site: t.site, child_smiles: t.child_smiles, reward: t.reward_delta, chosen_by: "user", target_id: s.target_id, session_id: s.session_id, t: t.t })).join("\n") + "\n";
    return new Response(text, { headers: { "Content-Type": "application/x-ndjson" } });
  }
  return J({ detail: "dev shim: no route " + p }, 404);
};
console.info("[dev] manual fetch shim installed (fixture data)");
